import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("sign-in ignores the case of the email address", { tag: "@LIF-11" }, async ({ request }) => {
    // Arrange
    const mixedCaseEmail = "Member@Northwind.TEST";

    // Act
    const login = await request.post("/api/auth/login", {
      data: { email: mixedCaseEmail, password: PASSWORD },
    });

    // Assert
    const session = await expectStatus<{ access_token: string }>(login, 200);
    const me = await request.get("/api/me", {
      headers: { Authorization: `Bearer ${session.access_token}` },
    });
    const profile = await expectStatus<{ email: string }>(me, 200);
    expect(profile.email).toBe(USERS.member);
  });
});
